        string s, t;
        cin >> s >> t;
        for (char &c : s) cnt1[c - 'a'] ++;
        for (char &c : t) cnt2[c - 'a'] ++;
        bool answer = true;
        for (int i = 0; i < 26; ++i)
            if (cnt1[i] != cnt2[i]) 
                answer = false;
        puts(answer ? "YES" : "NO");
    }
}

